-- Migration 0066_court_document_network: generated by hand to match drizzle-kit output (table, keys, index), grants and RLS hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #485)
-- The court document network (#485, D-048 tier 3). contributed_document is a global table
-- (GLOBAL_TABLES, no RLS, no workspace_id): public court documents a workspace opted in to share,
-- stored once by content hash. The app role may SELECT, INSERT and UPDATE it (withdrawal blanks the
-- content, it never deletes the row); the clerk role has no privileges on it. contribution_ledger is
-- the tenant-side link under FORCE RLS with ws_isolation. workspace_settings gets the opt-in column,
-- off by default. Expand only: new tables and one defaulted column.
ALTER TABLE "workspace_settings" ADD COLUMN "contribute_public_court_documents" boolean DEFAULT false NOT NULL;--> statement-breakpoint
CREATE TABLE "contributed_document" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"source_id" text NOT NULL,
	"kind" text NOT NULL,
	"forum_label" text,
	"listing_date" date,
	"content" text,
	"sha256" text NOT NULL,
	"provenance" text DEFAULT 'contributed' NOT NULL,
	"contributed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"retention_until" timestamp with time zone NOT NULL,
	"withdrawn_at" timestamp with time zone,
	CONSTRAINT "contributed_document_sha256_uq" UNIQUE("sha256"),
	CONSTRAINT "contributed_document_kind_chk" CHECK ("contributed_document"."kind" in ('cause_list', 'order')),
	CONSTRAINT "contributed_document_provenance_chk" CHECK ("contributed_document"."provenance" = 'contributed'),
	CONSTRAINT "contributed_document_sha256_chk" CHECK ("contributed_document"."sha256" ~ '^[0-9a-f]{64}$'),
	CONSTRAINT "contributed_document_withdrawn_chk" CHECK (("contributed_document"."withdrawn_at" is null) = ("contributed_document"."content" is null))
);
--> statement-breakpoint
CREATE TABLE "contribution_ledger" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"contributed_document_id" uuid NOT NULL,
	"document_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "contribution_ledger_workspace_doc_uq" UNIQUE("workspace_id","contributed_document_id")
);
--> statement-breakpoint
ALTER TABLE "contributed_document" ADD CONSTRAINT "contributed_document_source_id_source_id_fk" FOREIGN KEY ("source_id") REFERENCES "public"."source"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "contribution_ledger" ADD CONSTRAINT "contribution_ledger_contributed_document_id_contributed_document_id_fk" FOREIGN KEY ("contributed_document_id") REFERENCES "public"."contributed_document"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "contribution_ledger" ADD CONSTRAINT "contribution_ledger_workspace_id_organization_id_fk" FOREIGN KEY ("workspace_id") REFERENCES "public"."organization"("id") ON DELETE cascade ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "contributed_document_lookup_idx" ON "contributed_document" USING btree ("source_id","kind","listing_date");--> statement-breakpoint
CREATE INDEX "contribution_ledger_workspace_id_idx" ON "contribution_ledger" USING btree ("workspace_id");--> statement-breakpoint
REVOKE ALL ON "contributed_document" FROM PUBLIC, causedeck_app, causedeck_clerk;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "contributed_document" TO causedeck_app;--> statement-breakpoint
ALTER TABLE "contribution_ledger" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
ALTER TABLE "contribution_ledger" FORCE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "ws_isolation" ON "contribution_ledger" AS PERMISSIVE FOR ALL TO PUBLIC USING (workspace_id = nullif(current_setting('app.workspace_id', true), '')::uuid) WITH CHECK (workspace_id = nullif(current_setting('app.workspace_id', true), '')::uuid);
